script:
card({ name: "Quiz night", icon: 'quiz', permissions: ['sound'] });
const words = {
  add: "Question? right answer / wrong / wrong",
  how: "Write a question, then its answers split by /. Put the right one first.",
  count: "{p0} questions so far",
  start: "Start the quiz",
  question: "Question {p0} of {p1}",
  answered: "{p0} answered",
  next: "Next question",
  finish: "See the scores",
  done: "Final scores",
  again: "New quiz",
  once: "One answer each",
  onlyHost: "Only {p0} can move on",
  needTwo: "Give at least two answers, split by /",
  started: "The quiz has started",
  waitHost: "Waiting for {p0} to move on",
  full: "Twenty questions at most",
  onlySender: "Only the person who sent the card can do that",
  writing: "The quiz is being written. It starts soon.",
  hostOnly: "You wrote the answers, so you host",
  right: "Right answer: {p0}",
  who: "Answered: {p0}",
};

// Whoever sent the card writes the questions and hosts; everyone else
// answers. One to show how it goes: add your own after it.
function init() {
  const sample = { text: '7 × 8 = ?', answers: ['54', '56', '64'], right: 1 };
  return { questions: [sample], at: -1, host: null, hostName: '', picks: {}, score: {}, names: {} };
}

on.add = (s, args, ctx) => {
  if (ctx.author !== ctx.sender) throw words.onlySender;
  if (s.at >= 0) throw words.started;
  if (s.questions.length >= 20) throw words.full;
  const line = String(args.value || '');
  const mark = line.indexOf('?');
  const text = (mark < 0 ? line : line.slice(0, mark + 1)).trim().slice(0, 160);
  const answers = (mark < 0 ? '' : line.slice(mark + 1)).split('/').map(a => a.trim().slice(0, 60)).filter(a => a);
  if (!text || answers.length < 2) throw words.needTwo;
  // Shuffle, remembering where the right answer went.
  const order = answers.map((a, i) => i);
  for (let i = order.length - 1; i > 0; i--) {
    const j = Math.floor(ctx.random() * (i + 1));
    const t = order[i];
    order[i] = order[j];
    order[j] = t;
  }
  s.questions.push({ text, answers: order.map(i => answers[i]), right: order.indexOf(0) });
};

on.start = (s, args, ctx) => {
  if (ctx.author !== ctx.sender) throw words.onlySender;
  s.at = 0;
  s.host = ctx.author;
  s.hostName = ctx.authorName;
  s.picks = {};
};

on.answer = (s, args, ctx) => {
  if (ctx.author === s.host) throw words.hostOnly;
  if (s.picks[ctx.author] !== undefined) throw words.once;
  s.picks[ctx.author] = args.pick;
  s.names[ctx.author] = ctx.authorName;
  s.score[ctx.author] = s.score[ctx.author] || 0;
  if (args.pick === s.questions[s.at].right) {
    s.score[ctx.author]++;
    ctx.sound('coin', { for: ctx.author });
  } else {
    ctx.sound('buzz', { for: ctx.author });
  }
};

on.next = (s, args, ctx) => {
  if (ctx.author !== s.host) throw words.onlyHost.replace('{p0}', s.hostName);
  s.at++;
  s.picks = {};
  if (s.at >= s.questions.length) ctx.sound('win');
};

on.again = (s, args, ctx) => {
  if (ctx.author !== ctx.sender) throw words.onlySender;
  return init();
};

function scores(s) {
  const ids = Object.keys(s.score).sort((a, b) => s.score[b] - s.score[a]);
  return ids.map((id, i) => row([text((i + 1) + '. ' + s.names[id]), badge(String(s.score[id]), { tone: i === 0 ? 'success' : undefined })], { align: 'between' }));
}

function view(s, me) {
  const n = s.questions.length;
  if (s.at < 0) {
    if (!me.isSender) {
      return column([
        text(words.writing, { align: 'center' }),
        badge(words.count.replace('{p0}', n), { tone: 'accent', align: 'center' }),
      ]);
    }
    // The writer sees the questions and their right answers.
    return column([
      n > 0 && button(words.start, 'start', null, { tone: 'accent', align: 'center' }),
      ...s.questions.map((q, i) => text((i + 1) + '. ' + q.text + '  ✓ ' + q.answers[q.right], { size: 'small' })),
      text(words.how, { tone: 'muted' }),
      input('question', words.add, 'add'),
    ]);
  }
  if (s.at >= n) {
    return column([
      text(words.done, { size: 'large', bold: true, align: 'center' }),
      ...scores(s),
      me.isSender && button(words.again, 'again', null, { tone: 'muted', align: 'center' }),
    ]);
  }
  const q = s.questions[s.at];
  const mine = s.picks[me.id];
  const answered = Object.keys(s.picks).length;
  if (me.id === s.host) {
    // The host sees the right answer and who has answered, and moves on.
    return column([
      text(words.question.replace('{p0}', s.at + 1).replace('{p1}', n), { size: 'small', tone: 'muted', align: 'center' }),
      progress((s.at + 1) / n),
      text(q.text, { size: 'large', bold: true, align: 'center' }),
      text(words.right.replace('{p0}', q.answers[q.right]), { tone: 'success', align: 'center' }),
      text(words.who.replace('{p0}', Object.keys(s.picks).map(id => s.names[id]).join(', ') || '–'), { size: 'small', tone: 'muted', align: 'center' }),
      button(s.at + 1 < n ? words.next : words.finish, 'next', null, { tone: 'accent', align: 'center' }),
    ]);
  }
  return column([
    text(words.question.replace('{p0}', s.at + 1).replace('{p1}', n), { size: 'small', tone: 'muted', align: 'center' }),
    progress((s.at + 1) / n),
    text(q.text, { size: 'large', bold: true, align: 'center' }),
    column(q.answers.map((a, i) => button(a, 'answer', { pick: i }, {
      tone: mine === undefined ? 'accent' : i === q.right ? 'success' : i === mine ? 'danger' : 'muted',
      align: 'center',
    }))),
    text(words.answered.replace('{p0}', answered), { size: 'small', tone: 'muted', align: 'center' }),
    text(words.waitHost.replace('{p0}', s.hostName), { size: 'small', tone: 'muted', align: 'center' }),
  ]);
}
